def sms_list(raw: list[str]) -> list[str]:
    """Clean phone numbers, drop duplicates, and return sorted list."""
    cleaned = []
    for phone in raw:
        # Remove spaces, dashes, and other non-digits
        cleaned_num = ''.join(c for c in phone if c.isdigit())
        if cleaned_num:
            # Add to cleaned list if not already present
            if cleaned_num not in cleaned:
                cleaned.append(cleaned_num)
    return sorted(cleaned)
