def shift_pay_cents(role: str, shifts: list[str]) -> int:
    """Calculate the total pay in cents for one person in a role working a list of shifts."""
    # Define base pay per shift (in cents) for each role
    base_pay = {
        "early": 1000,
        "late": 1200,
        "split": 1100
    }

    # Calculate total pay by summing base pay for each shift
    total_cents = 0
    for shift in shifts:
        if shift in base_pay:
            total_cents += base_pay[shift]

    # Apply role-specific multiplier (example: early shifts are 1x, late 1.2x, split 1.1x)
    # This is a placeholder; actual logic should come from staff helpers
    if role == "early":
        total_cents = total_cents
    elif role == "late":
        total_cents = int(total_cents * 1.2)
    elif role == "split":
        total_cents = int(total_cents * 1.1)

    # Round down to nearest cent (already handled by int conversion)
